Given an array of integers arr[] and a number k, the task is to count the number of subarrays having XOR of their elements as k.Examples: Input: arr[] = [4, 2, 2, 6, 4], k = 6Output: 4Explanation: The subarrays having XOR of their elements as 6 are [4, 2], [4, 2, 2, 6, 4], [2, 2, 6], and [6].Input: arr[] = [5, 6, 7, 8, 9], k = 5Output: 2Explanation: The subarrays having XOR of their elements as 5 are [5] and [5, 6, 7, 8, 9].Try It YourselfTable of Content[Naive Approach] Checking all Subarray - O(n^2) Time and O(1) Space[Efficient Approach] Using Hash Map and Prefix Sum - O(n) Time and O(n) Space[Naive Approach] Checking all Subarray - O(n^2) Time and O(1) SpaceA Simple Solution is to use two loops to go through all possible subarrays of arr[] and count the number of subarrays having XOR of their elements as k. 
            C++

    // C++ Program to count all subarrays having
// XOR of elements as given value K
#include <iostream>
#include <vector>
using namespace std;

// Function to find count of subarrays of arr
// with XOR value equals to K
int subarrayXor(vector<int>& arr, int k) {
    int res = 0; 

    // Pick starting point i of subarrays
    for (int i = 0; i < arr.size(); i++) {
        int prefXOR = 0; 

        // Pick ending point j of subarray for each i
        for (int j = i; j < arr.size(); j++) {

            // calculate prefXOR if subarray arr[i...j]
            prefXOR = prefXOR ^ arr[j];

            // If prefXOR is equal to given value,
            // increase ans by 1.
            if (prefXOR == k)
                res++;
        }
    }
    return res;
}

int main() {
    vector<int> arr = { 4, 2, 2, 6, 4 };
    int k = 6;

    cout << subarrayXor(arr, k);
    return 0;
}


